"""Plot fitness over generations for all specified experiments (average and max)"""import jsonimport configimport matplotlib.pyplot as pltimport pandas as pdfrom database_components import Experiment, Generation, Individual, Populationfrom sqlalchemy import selectimport argparsefrom revolve2.experimentation.database import OpenMethod, open_database_sqlitedef plotFitness(df: pd.DataFrame, name: str, figName: str, fMax: float) -> None:    """    Plot the mean and max fitnesses of all experiments in a dataframe.    """    agg_per_experiment_per_generation = (        df.groupby(["experiment_id", "generation_index"])        .agg({name: ["max", "mean"]})        .reset_index()    )    agg_per_experiment_per_generation.columns = [        "experiment_id",        "generation_index",        "max_fitness",        "mean_fitness",    ]    agg_per_generation = (        agg_per_experiment_per_generation.groupby("generation_index")        .agg({"max_fitness": ["mean", "std"], "mean_fitness": ["mean", "std"]})        .reset_index()    )    agg_per_generation.columns = [        "generation_index",        "max_fitness_mean",        "max_fitness_std",        "mean_fitness_mean",        "mean_fitness_std",    ]        plt.figure()    # Plot max    plt.plot(        agg_per_generation["generation_index"],        agg_per_generation["max_fitness_mean"],        label="Max fitness",        color="b",    )    plt.fill_between(        agg_per_generation["generation_index"],        agg_per_generation["max_fitness_mean"] - agg_per_generation["max_fitness_std"],        agg_per_generation["max_fitness_mean"] + agg_per_generation["max_fitness_std"],        color="b",        alpha=0.2,    )    # Plot mean    plt.plot(        agg_per_generation["generation_index"],        agg_per_generation["mean_fitness_mean"],        label="Mean fitness",        color="r",    )    plt.fill_between(        agg_per_generation["generation_index"],        agg_per_generation["mean_fitness_mean"]        - agg_per_generation["mean_fitness_std"],        agg_per_generation["mean_fitness_mean"]        + agg_per_generation["mean_fitness_std"],        color="r",        alpha=0.2,    )    title = f"Mean and max {name} across repetitions with std as shade"    if figName != None: title += ("\n" + figName)    plt.xlim([0, config.NUM_GENERATIONS_BODY])    plt.ylim([-1, fMax])    plt.xlabel("Generation index")    plt.ylabel("Fitness\n(no. of targets reached)")    plt.title(title)    plt.grid(which="major", axis="both")    plt.legend()    plt.show()def plotDelta(df: pd.DataFrame, figName: str, dMax: float) -> None:    """    Plot the average learning delta per generation over all experiments.    """    agg_exp_gen = (        df.groupby(["experiment_id", "generation_index"])        .agg({"fitness": ["mean"]})        .reset_index()    )    agg_exp_gen.columns = [        "experiment_id",        "generation_index",        "mean_fitness",    ]        # Group and compute deltas + cleanup    agg_exp_gen["delta"] = agg_exp_gen.groupby("experiment_id")["mean_fitness"].diff()    agg_exp_gen = agg_exp_gen.dropna(subset=["delta"])    summary = agg_exp_gen.groupby("generation_index")["delta"].agg(["mean", "std"]).reset_index()        # Plot w/ std shade    plt.figure()    plt.plot(        summary.generation_index,        summary.mean,        label="Mean learning delta",        color="lime")        plt.fill_between(        summary.generation_index,        summary.mean - summary.std,        summary.mean + summary.std,        color="lime", alpha=0.2)        def genDF(fileName):    """    Generates a dataframe for an experiment.    """    dbengine = open_database_sqlite(        fileName, open_method=OpenMethod.OPEN_IF_EXISTS    )    df = pd.read_sql(        select(            Experiment.id.label("experiment_id"),            Generation.generation_index,            Individual.fitness,        )        .join_from(Experiment, Generation, Experiment.id == Generation.experiment_id)        .join_from(Generation, Population, Generation.population_id == Population.id)        .join_from(Population, Individual, Population.id == Individual.population_id),        dbengine,    )        return dfdef main() -> None:    """Run the program."""    # Check for passed arguments    parser = argparse.ArgumentParser(description="Plot the max and mean fitnesses for specified experiments.")    parser.add_argument("-name", type=str, help="Specify the name of the JSON containing databases to combine.")    parser.add_argument("-figName", type=str, help="Specify custom figure title.")    parser.add_argument("-fMax", type=float, default=2.25, help="Maximum fitness in axis. Default: 2.25")    args = parser.parse_args()        if args.name:        # Import JSON file containing database names        dbList = args.name + ".json"        with open(dbList, 'r') as file:            dbFile = json.load(file)            dbs = dbFile.get("Databases", [])        assert len(dbs) > 0, "Need to import at least 2 databases to combine."                # Read first database in list        data = genDF("Databases/"+dbs[0]+".sqlite")        dbs = dbs[1:]                # Read next databases and combine into one        for fileName in dbs:            df = genDF("Databases/"+fileName+".sqlite")            df.experiment_id += data.experiment_id.max()            data = pd.concat([data, df], ignore_index=True)        print(f"Total of {data.experiment_id.max()} experiments aggregated.")                # Generate plot        plotFitness(df=data, name="fitness", figName=args.figName, fMax=args.fMax)            else: print("Pass database name with '-name'. Closing now.")if __name__ == "__main__":    main()